from taf.nms.nom.schemas.base import SchemaObject, SchemaField, SchemaObjects


class CertificateAttributes(SchemaObject):
    issuer = SchemaField(name="issuer")
    name = SchemaField(name="name")
    public_key_algorithm = SchemaField(name="public_key_algorithm")
    serial_number = SchemaField(name="serial_number")
    signature_algorithm = SchemaField(name="signature_algorithm")
    subject = SchemaField(name="subject")
    valid_to = SchemaField(name="valid_to")

    def __init__(self, issuer, name, public_key_algorithm, serial_number,
                 signature_algorithm, subject, valid_to):
        self.issuer = issuer
        self.name = name
        self.public_key_algorithm = public_key_algorithm
        self.serial_number = serial_number
        self.signature_algorithm = signature_algorithm
        self.subject = subject
        self.valid_to = valid_to
        super(CertificateAttributes, self).__init__()


class CertificateListResponse(SchemaObjects):
    schema = CertificateAttributes
